pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 depositAmount, uint256 withdrawAmount) public {
        vm.assume(actor != address(0) && actor != address(this));
        vm.assume(depositAmount > 0 && depositAmount <= address(this).balance);
        vm.assume(withdrawAmount <= depositAmount);

        // Make a deposit as a non-owner
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");

        uint256 balanceBefore = address(c).balance;
        uint256 depositsBefore = c.depositsCount();

        // Withdraw as the same non-owner actor
        vm.prank(actor);
        try c.withdrawAll() {
            // If withdrawAll succeeds, the invariant must hold
            assertTrue(address(c).balance >= c.depositsCount());
        } catch {
            // If withdrawAll reverts, the balance and deposits count must remain unchanged
            assertTrue(address(c).balance == balanceBefore && c.depositsCount() == depositsBefore);
        }
    }
}

