import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 depositAmount) public {
        // amount must not exceed the contract's balance for the withdraw to proceed
        // Start with funding the owner and depositing into the contract
        address owner = c.owner();
        vm.deal(owner, amount);
        vm.prank(owner);
        (bool depositSuccess, ) = address(c).call{value: amount}("");
        require(depositSuccess, "Initial deposit failed");
        require(amount > 0, "Amount must be positive");

        // The owner withdraws the given amount
        vm.prank(owner);
        try c.withdraw(amount) {
            // withdraw succeeded
        } catch {
            // withdraw reverted, test the property with what we have
        }

        // Now attempt a deposit via the fallback to check if the contract is still alive
        vm.deal(owner, depositAmount);
        vm.prank(owner);
        (bool stillAlive, ) = address(c).call{value: depositAmount}("");
        // The reference contract always accepts this deposit; the buggy contract selfdestructs and cannot receive it if withdraw succeeded previously
        assertTrue(stillAlive);
    }
}

