pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 amount, address owner) public {
        vm.assume(owner != address(0) && owner != address(this) && owner != address(c));
        vm.assume(amount > 0);
        vm.deal(owner, amount);
        vm.prank(owner);
        // make owner the contract owner by sending enough ether via fallback
        c = new C();
        vm.deal(owner, amount * 2);
        vm.prank(owner);
        address(c).call{value: amount}();
        // now c.owner is owner, c balance is amount
        // deploy adversarial helper that always reverts on receiving ether
        Reverter reverter = new Reverter();
        // send some eth to reverter so it has code (optional) but not needed
        vm.prank(owner);
        c.withdraw(amount);
        // after withdraw, contract balance should be 0, owner's balance increased
        // now try sendMoney to reverter, which will revert
        bool ok;
        vm.prank(owner);
        try c.sendMoney(address(reverter), amount) { ok = true; } catch { ok = false; }
        // reference: withdraw transferred amount to owner, balance is 0, sendMoney with full balance fails -> ok=false
        // mutant: withdraw may silently fail, balance remains amount, sendMoney with amount succeeds -> ok=true
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

