contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address owner) public {
        vm.assume(owner != address(0));
        vm.assume(amount > 0);
        // Make the fuzzed address the owner
        vm.prank(c.owner());
        c.sendMoney(owner, 0); // Not needed for ownership transfer, so we directly manipulate storage via constructor? 
        // Actually, we need to set the owner. Since C has no setOwner, we deploy C with the fuzzed owner.
        // But setUp() already deploys c with msg.sender as owner. To test with a fuzzed owner, we must deploy a new C from the fuzzed owner.
        // We'll do it inside the test:
        vm.startPrank(owner);
        C c2 = new C();
        vm.deal(address(c2), amount);
        uint256 balanceBefore = address(c2).balance;
        bool ok = true;
        try c2.withdraw(amount) { ok = true; } catch { ok = false; }
        uint256 balanceAfter = address(c2).balance;
        vm.stopPrank();
        assertTrue(!ok || balanceAfter == balanceBefore - amount);
    }
}

