contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to 0..address(c).balance to stay within contract funds
        uint256 balanceBefore = address(c).balance;
        amount = bound(amount, 0, balanceBefore);

        // We need an owner EOA; use a pre-funded address that becomes owner
        address owner = c.owner();
        vm.deal(owner, 0); // ensure owner is an EOA (already is, but explicit)
        // Send some ether to the contract so it has funds
        vm.deal(address(c), amount);

        vm.prank(owner);
        // try/catch to observe revert status
        bool ok;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }

        uint256 balanceAfter = address(c).balance;

        // If the call did not revert, the contract balance must have decreased by exactly amount
        assertTrue(!ok || balanceBefore - balanceAfter == amount);
    }
}

